"""Configuration loading helpers."""

from pathlib import Path


def config_path(name: str) -> Path:
    return Path("configs") / name


def load_retry_policy() -> dict:
    return {"initial_delay_seconds": 30, "max_attempts": 5}


def _parse_scalar(value: str):
    value = value.strip()
    if value == "true":
        return True
    if value == "false":
        return False
    return value


def load_feature_flags() -> dict:
    """Load feature flags from configs/feature_flags.yaml.

    Parses the simple nested-mapping YAML subset used by the fixture. Returns
    an empty dict when the file is missing or unreadable.
    """
    path = config_path("feature_flags.yaml")
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return {}

    root: dict = {}
    stack: list[tuple[int, dict]] = [(-1, root)]
    for raw_line in lines:
        line = raw_line.rstrip()
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        indent = len(line) - len(line.lstrip())
        if ":" not in line:
            continue
        key, _, value = line.partition(":")
        key = key.strip()
        value = value.strip()
        while stack and indent <= stack[-1][0]:
            stack.pop()
        parent = stack[-1][1]
        if value:
            parent[key] = _parse_scalar(value)
        else:
            child: dict = {}
            parent[key] = child
            stack.append((indent, child))
    return root

